                export class FileUpload extends Base{
                    /**
                     * Represents a file upload cell type.
                     * @extends GC.Spread.Sheets.CellTypes.Base
                     * @class
                     * @example
                     * ```javascript
                     * // set a FileUpload celltype
                     * const cellType1 = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * sheet.setCellType(1, 1, cellType1);
                     * // FileUpload support the valuePath property, will parse the cell value with valuePath to GC.Spread.Sheets.CellTypes.IFileInfo
                     * sheet.getCellType(1, 1).valuePath("blob");
                     * sheet.setValue(1, 1, blob); // value path is "blob"
                     * sheet.getCellType(2, 2).valuePath("dataUrl");
                     * sheet.setValue(2, 2, dataUrl); // value path is "dataUrl"
                     * sheet.getCellType(3, 3).valuePath(undefined);
                     * sheet.setValue(3, 3, { name: 'test1.png', blob: blob }); // value path is undefined
                     * sheet.setValue(3, 3, { name: 'test2.txt', dataUrl: dataUrl }); // value path is undefined
                     * ```
                     */
                    constructor();
                    /**
                     * Customize personalized preview logic and UI display by setting event callbacks or SJS commands after clicking the preview button.
                     * @type {string | ((file: GC.Spread.Sheets.CellTypes.IFilePreviewInfo) => void)}
                     * @returns {void}
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * // Customize your preview function.
                     * fileUpload.previewCommand = function (fileInfo) {
                     *    // Custom preview logic
                     * }
                     *
                     * // Customize your preview command.
                     * fileUpload.previewCommand = 'openPreviewDialog';
                     *
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    previewCommand?: string | ((file: GC.Spread.Sheets.CellTypes.IFilePreviewInfo) => void);
                    /**
                     * Gets or sets the file types that can be uploaded.
                     * @param {string} value The file types that can be uploaded.
                     * @returns {string} Returns the file types that can be uploaded.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.accept('image/*');
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    accept(value?: string): string;
                    /**
                     * Gets or sets whether to display the file clear button.
                     * @param {string} value Whether to display the file clear button.
                     * @returns {string} Returns the currently displayed file clear button.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.isClearEnabled(false);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    isClearEnabled(value?: boolean): boolean;
                    /**
                     * Gets or sets whether to display the file download button.
                     * @param {string} value Whether to display the file download button.
                     * @returns {string} Returns the currently displayed file download button.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.isDownloadEnabled(false);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    isDownloadEnabled(value?: boolean): boolean;
                    /**
                     * Gets or sets whether to display the file preview button.
                     * @param {string} value Whether to display the file preview button.
                     * @returns {string} Returns the currently displayed file preview button.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.isPreviewEnabled(false);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    isPreviewEnabled(value?: boolean): boolean;
                    /**
                     * Gets or sets the margin bottom value.
                     * @param {number} value The margin bottom value.
                     * @returns {number} If no value is set, return current margin bottom.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.marginBottom(10);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    marginBottom(value?: number): number;
                    /**
                     * Gets or sets the margin left value.
                     * @param {number} value The margin left value.
                     * @returns {number} If no value is set, return current margin left.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.marginLeft(10);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    marginLeft(value?: number): number;
                    /**
                     * Gets or sets the margin right value.
                     * @param {number} value The margin right value.
                     * @returns {number} If no value is set, return current margin right.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.marginRight(10);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    marginRight(value?: number): number;
                    /**
                     * Gets or sets the margin top value.
                     * @param {number} value The margin top value.
                     * @returns {number} If no value is set, return current margin top.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.marginTop(10);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    marginTop(value?: number): number;
                    /**
                     * Gets or sets the maximum file size that can be uploaded.
                     * @param {number} value The maximum file size that can be uploaded.
                     * @returns {number} Returns the maximum file size that can be uploaded.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.maxSize(10000);
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * ```
                     */
                    maxSize(value?: number): number;
                    /**
                     * Gets or sets the value path for fileUpload cellType, the cell will get vale by the valuePath from the cell fileInfo.
                     * @param {string} value The value path value.
                     * @returns {string} If no value is set, return current value path, the default value path is dataUrl.
                     * @example
                     * ```javascript
                     * // This example creates a file upload cell and setValue with dataUrl.
                     * const fileUpload = new GC.Spread.Sheets.CellTypes.FileUpload();
                     * fileUpload.valuePath("dataUrl"); // set valuePath dataUrl, default is dataUrl
                     * activeSheet.getCell(1, 1).cellType(fileUpload);
                     * activeSheet.setValue(1, 1, 'data:text/plain;base64,MQ==')
                     * ```
                     */
                    valuePath(value?: string): string;
                }

                export class HyperLink extends Base{
                    /**
                     * Represents the hyperlink cell.
                     * @extends GC.Spread.Sheets.CellTypes.Base
                     * @class
                     * @example
                     * ```javascript
                     * var cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FF2235");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * activeSheet.getCell(1, 1).cellType(cellType).value("http://www.spreadjs.com/");
                     * activeSheet.getCell(1, -1).height(30);
                     * ```
                     * @example
                     * ```javascript
                     * var cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FF2235");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * activeSheet.getCell(0, 2).cellType(cellType).value("formula.html");
                     * ```
                     */
                    constructor();
                    /**
                     *  Gets or sets whether to move to the active cell when clicked.
                     * @param {boolean} value Whether to move to the active cell when clicked.
                     * @returns {boolean | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns a value that indicates whether to move to the active cell; otherwise, returns the hyperlink cell type.
                     * @example
                     * ```javascript
                     * //This example uses the activeOnClick method.
                     * var h1 = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * h1.text("SpreadsJS");
                     * h1.linkToolTip("link to SpreadJS Web page");
                     * h1.linkColor("rgb(0, 100, 200)");
                     * h1.visitedLinkColor("rgb(0, 200, 100)");
                     * h1.activeOnClick(true);
                     * activeSheet.setCellType(1, 1, h1);
                     * activeSheet.getCell(1, 1, GC.Spread.Sheets.SheetArea.viewport).value("http://www.spreadjs.com/").hAlign(GC.Spread.Sheets.HorizontalAlign.center);
                     * ```
                     */
                    activeOnClick(value?: boolean): any;
                    /**
                     * Gets or sets the color of the hyperlink.
                     * @param {string} value The hyperlink color.
                     * @returns {string | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns the hyperlink color; otherwise, returns the hyperLink cell type.
                     * @example
                     * ```javascript
                     * //This example creates a hyperlink cell.
                     * cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FF2235");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * activeSheet.getCell(1, 1).cellType(cellType).value("http://www.spreadjs.com/");
                     * activeSheet.getCell(1, -1).height(30);
                     * ```
                     */
                    linkColor(value?: string): any;
                    /**
                     * Gets or sets the tooltip for the hyperlink.
                     * @param {string} value The tooltip text.
                     * @returns {string | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns the tooltip text; otherwise, returns the hyperLink cell type.
                     * @example
                     * ```javascript
                     * //This example creates a hyperlink cell.
                     * cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FF2235");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * activeSheet.getCell(1, 1).cellType(cellType).value("http://www.spreadjs.com/");
                     * activeSheet.getCell(1, -1).height(30);
                     * ```
                     */
                    linkToolTip(value?: string): any;
                    /**
                     *  Gets or sets the callback of the hyperlink, If execute the function will represent the context for the callback.
                     * @param {Function} value The callback of the hyperlink.
                     * @returns {Function | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, return a value that indicates the callback of the hyperlink; otherwise, returns the hyperlink cell type.
                     * @example
                     * ```javascript
                     * //This example sets the tab color when selecting the hyperlink.
                     * var h2 = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * h2.text("set sheet tab style");
                     * h2.linkToolTip("set sheet tab style");
                     * h2.linkColor("blue");
                     * h2.visitedLinkColor("#FF2235");
                     * activeSheet.getCell(2, 1).cellType(h2).value("set sheet tab style").hAlign(GC.Spread.Sheets.HorizontalAlign.center);
                     * h2.activeOnClick(true);
                     *             h2.onClickAction(function () {
                     *                 var setSheetTabColor = {
                     *                     canUndo: true,
                     *                     execute: function (context, options, isUndo) {
                     *                         activeSheet.name("Hyperlink");
                     *                         activeSheet.options.sheetTabColor = "red";
                     *                     }
                     *                 };
                     *                 var commandManager = spread.commandManager();
                     *                 var commandName = "setSheetTabStyle";
                     *                 commandManager.register(commandName, setSheetTabColor, null, false, false, false, false);
                     *                 commandManager.execute({cmd: commandName})
                     *             });
                     * ```
                     */
                    onClickAction(value?: Function): any;
                    /**
                     *  Gets or sets the type for the hyperlink's target.
                     * @param {GC.Spread.Sheets.CellTypes.HyperLinkTargetType} value The hyperlink's target type.
                     * @returns {GC.Spread.Sheets.CellTypes.HyperLinkTargetType | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns the hyperlink's target type; otherwise, returns the hyperLink cell type.
                     * @example
                     * ```javascript
                     * //This example creates a hyperlink cell.
                     * var cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FFFF00");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * cellType.target(GC.Spread.Sheets.CellTypes.HyperLinkTargetType.self);
                     * activeSheet.getCell(0, 2).cellType(cellType).value("http://www.spreadjs.com/");
                     * ```
                     */
                    target(value?: GC.Spread.Sheets.CellTypes.HyperLinkTargetType): any;
                    /**
                     * Gets or sets the text string for the hyperlink.
                     * @param {string} value The text displayed in the hyperlink.
                     * @returns {string | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns the text in the hyperlink; otherwise, returns the hyperLink cell type.
                     * @example
                     * ```javascript
                     * //This example creates a hyperlink cell.
                     * var cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FFFF00");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * cellType.target(GC.Spread.Sheets.CellTypes.HyperLinkTargetType.self);
                     * activeSheet.getCell(0, 2).cellType(cellType).value("http://www.spreadjs.com/");
                     * ```
                     */
                    text(value?: string): any;
                    /**
                     * Gets or sets the color of visited links.
                     * @param {string} value The visited link color.
                     * @returns {string | GC.Spread.Sheets.CellTypes.HyperLink} If no value is set, returns the visited link color; otherwise, returns the hyperLink cell type.
                     * @example
                     * ```javascript
                     * //This example creates a hyperlink cell.
                     * var cellType = new GC.Spread.Sheets.CellTypes.HyperLink();
                     * cellType.linkColor("blue");
                     * cellType.visitedLinkColor("#FFFF00");
                     * cellType.text("SpreadJS");
                     * cellType.linkToolTip("Company Web Site");
                     * cellType.target(GC.Spread.Sheets.CellTypes.HyperLinkTargetType.self);
                     * activeSheet.getCell(0, 2).cellType(cellType).value("http://www.spreadjs.com/");
                     * ```
                     */
                    visitedLinkColor(value?: string): any;
                }

