                export class Calendar{
                    /**
                     * Creates a calendar with the provided work weeks.
                     * @class
                     * @param {string} name - A string value specifies the name of this calendar.
                     * @param {GC.Spread.Sheets.GanttSheet.WorkWeek} [defaultWorkWeek] - Specifies the default work times of each day of week. If not specified, the work times will be same as the standard calendar.
                     * @param {GC.Spread.Sheets.GanttSheet.CustomWorkWeek[]} [customWorkWeeks] - Specifies the customized work times of each day of week for the specified date range.
                     * @classdesc Represents a calender for scheduling, which defines the work times of each day.
                     */
                    constructor(name: string,  defaultWorkWeek?: GC.Spread.Sheets.GanttSheet.WorkWeek,  customWorkWeeks?: GC.Spread.Sheets.GanttSheet.CustomWorkWeek[]);
                    /**
                     * Gets or sets the custom work weeks for this calendar.
                     * Note do not modify a calendar in use. Instead, you could copy a calendar and make changes, then replace the original one.
                     * @type {GC.Spread.Sheets.GanttSheet.CustomWorkWeek[]}
                     */
                    customWorkWeeks: GC.Spread.Sheets.GanttSheet.CustomWorkWeek[];
                    /**
                     * Gets or sets the default work week for this calendar.
                     * Note do not modify a calendar in use. Instead, you could copy a calendar and make changes, then replace the original one.
                     * @type {GC.Spread.Sheets.GanttSheet.WorkWeek}
                     */
                    defaultWorkWeek: GC.Spread.Sheets.GanttSheet.WorkWeek;
                    /**
                     * The 24 hours calendar, which defines the work time as 24 hours by 7 days in a week.
                     * @type {GC.Spread.Sheets.GanttSheet.Calendar}
                     * @readonly
                     */
                    static hours24: GC.Spread.Sheets.GanttSheet.Calendar;
                    /**
                     * Gets or sets the calendar name.
                     * @type {string}
                     */
                    name: string;
                    /**
                     * The night-shift calendar, which defines the work time as 23:00 to 3:00 and 4:00 to 8:00 from Monday evening to Saturday morning.
                     * @type {GC.Spread.Sheets.GanttSheet.Calendar}
                     * @readonly
                     */
                    static nightShift: GC.Spread.Sheets.GanttSheet.Calendar;
                    /**
                     * The standard calendar, which defines the work time as 8:00 to 12:00 and 13:00 to 17:00 for Monday to Friday.
                     * @type {GC.Spread.Sheets.GanttSheet.Calendar}
                     * @readonly
                     */
                    static standard: GC.Spread.Sheets.GanttSheet.Calendar;
                    /**
                     * Copies the work weeks of this calendar to a new calendar.
                     * @param  {string} newName A string indicates the name of the new calendar.
                     * @returns  {GC.Spread.Sheets.GanttSheet.Calendar} The copy result.
                     */
                    copyTo(newName: string): GC.Spread.Sheets.GanttSheet.Calendar;
                }

                export class CalendarSettings{
                    /**
                     * Creates a calendar settings object. Internal used only.
                     * @class
                     * @classdesc Represents a calendar settings object to configure the parameters used by calendars and durations.
                     */
                    constructor();
                    /**
                     * Gets or sets a value that indicates how many work days have in a month. It is used in duration conversions and calculating. The default value is 20;
                     * @type {number}
                     * @default 20
                     */
                    daysPerMonth: number;
                    /**
                     * Gets or sets the decimal digits for formatting a duration value. This duration value will be rounded to the nearest decimal places. The default value is 3.
                     * @type {number}
                     * @default 3
                     */
                    defaultDurationDecimalDigits: number;
                    /**
                     * Gets or sets the default unit of duration. It is used in parsing or editing durations. The default value is 'Day'.
                     * @type {GC.Spread.Sheets.GanttSheet.DurationUnit}
                     * @default "Day"
                     */
                    defaultDurationUnit: GC.Spread.Sheets.GanttSheet.DurationUnit;
                    /**
                     * Gets or sets the default time for task finish. If the date for task finish has no time specified, then this time will be used. The default value is 17:00.
                     * @type {GC.Spread.Sheets.GanttSheet.Time}
                     */
                    defaultFinishTime: GC.Spread.Sheets.GanttSheet.Time;
                    /**
                     * Gets or sets the default time for task start. If the date for task start has no time specified, then this time will be used. The default value is 8:00.
                     * @type {GC.Spread.Sheets.GanttSheet.Time}
                     */
                    defaultStartTime: GC.Spread.Sheets.GanttSheet.Time;
                    /**
                     * Gets or sets a value that indicates how many hours have in a workday. It is used in duration conversions and calculating. The default value is 8;
                     * @type {number}
                     * @default 8
                     */
                    hoursPerDay: number;
                    /**
                     * Gets or sets a value that indicates how many hours have in a work week. It is used in duration conversions and calculating. The default value is 40;
                     * @type {number}
                     * @default 40
                     */
                    hoursPerWeek: number;
                    /**
                     * Gets or sets the labels for duration parsing and formatting. The value should have 6 strings, in the order as Minute, Hour, Day, Week, Month, and Year.
                     * @type {string[]}
                     */
                    unitLabels: string[];
                    /**
                     * Gets or sets the plurals labels for duration parsing and formatting. The value should have 6 strings, in the order as Minute, Hour, Day, Week, Month, and Year.
                     * @type {string[]}
                     */
                    unitLabelsPlurals: string[];
                    /**
                     * Gets or sets a value that indicates the first day of the week. It will affect how to display and calculate weeks. The default value is Sunday.
                     * @type {GC.Spread.Sheets.GanttSheet.DayOfWeek}
                     * @default GC.Spread.Sheets.GanttSheet.DayOfWeek.Sunday
                     */
                    weekStartOn: GC.Spread.Sheets.GanttSheet.DayOfWeek;
                }

                export class Collection<T>{
                    /**
                     * Creates an instance of Collection.
                     * @class
                     * @param {T[]} [items] The items of collection.
                     * @classdesc A collection of objects.
                     */
                    constructor();
                    /**
                     * Adds the item into list.
                     * @param  {T} item The item to add.
                     */
                    add(item: T): void;
                    /**
                     * Get all item form collection.
                     * @return {T[]} A collection item list.
                     */
                    all(): T[];
                    /**
                     * Removes all items from list.
                     */
                    clear(): void;
                    /**
                     * Get the item index from collection list.
                     * @param  {T} item The item of the collection.
                     * @return {number} The index of item in the collection list.
                     */
                    getIndexByItem(item: T): number;
                    /**
                     * Get the item with the corresponding index
                     * @param  {number} index The collection list index.
                     * @returns  {T} The rule with the specified name.
                     */
                    getItemAt(index: number): T;
                    /**
                     * Gets the item with the specified name.
                     * @param  {string} name A string value indicates the name of the rule.
                     * @returns  {T | null} The rule with the specified name.
                     */
                    getRule(name: string): T | null;
                    /**
                     * Insert the item into list.
                     * @param  {number} index The insert index.
                     * @param  {T} item The item to insert.
                     */
                    insert(item: T): void;
                    /**
                     * Get the collection list length.
                     * @return {number} The collection list length.
                     */
                    length(): number;
                    /**
                     * Removes the item from list.
                     * @param  {T} item The item to remove.
                     */
                    remove(item: T): void;
                    /**
                     * Delete the corresponding item from an index
                     * @param  {number} index The collection list index.
                     */
                    removeAt(index: number): void;
                    /**
                     * Set the item to index.
                     * @param {number} index The index to insert.
                     * @param {T} item The item.
                     */
                    setItemAt(index: number,  item: T): void;
                }

