            module IO{
                /**
                 * Gets the the values of specific reference path list from file directly.
                 * @static
                 * @param {GC.Spread.Sheets.IExternalReference[]} refList - The array of external reference.
                 * @param {GC.Spread.Sheets.IO.GetFileFunctionType} getFile - The function which return file or blob by the specified file path.
                 * @param {GC.Spread.Sheets.IO.GetPartialValuesSuccessCallbackType} getPartialValuesSuccessCallback - The success callback function which called when get values successfully.
                 * @param {GC.Spread.Sheets.IO.GetPartialValuesErrorCallbackType} getPartialValuesErrorCallback - The error callback function which called when get values failed.
                 * @example
                 * ```javascript
                 * function getFile (path) {
                 *   // return file by path
                 * }
                 * let refList = spread.getExternalReferences(true);
                 * GC.Spread.Sheets.IO.getPartialValues(refList, getFile, (externalValues) => {
                 *   // successCallback
                 *   spread.updateExternalReference(externalValues);
                 * }, (errorMsg) => {
                 *   // errorCallback
                 *   console.log(errorMsg);
                 * });
                 * ```
                 */
                function getPartialValues(refList: GC.Spread.Sheets.IExternalReference[],  getFile: GC.Spread.Sheets.IO.GetFileFunctionType,  getPartialValuesSuccessCallback: GC.Spread.Sheets.IO.GetPartialValuesSuccessCallbackType,  getPartialValuesErrorCallback: GC.Spread.Sheets.IO.GetPartialValuesErrorCallbackType): void;
                /**
                 * Register a unknown max digit width info to IO.
                 * @param {string} fontFamily The font family of default style's font.
                 * @param {number} fontSize The font size of default style's font(in point).
                 * @param {number} maxDigitWidth The  max digit width of default style's font.
                 * @returns {void}
                 * @example
                 * ```javascript
                 * // Register max digit width for a custom font
                 * GC.Spread.Sheets.IO.registerMaxDigitWidth("Arial", 12, 7.2);
                 * ```
                 */
                function registerMaxDigitWidth(fontFamily: string,  fontSize: number,  maxDigitWidth: number): void;

                /**
                 * @typedef GC.Spread.Sheets.IO.GetFileFunctionType
                 * @param {string} filePath - the file path.
                 * @returns {File | Blob} - Returns the file or file blob.
                 * @description get file by file path.
                 */
                export type GetFileFunctionType = 
                    (filePath: string) => (File | Blob)
                

                /**
                 * @typedef GC.Spread.Sheets.IO.GetPartialValuesErrorCallbackType
                 * @param {string} errorMsg - the error message.
                 * @description the error callback of get partial values.
                 */
                export type GetPartialValuesErrorCallbackType = 
                    (errorMsg: string) => void
                

                /**
                 * @typedef GC.Spread.Sheets.IO.GetPartialValuesSuccessCallbackType
                 * @param {GC.Spread.Sheets.ExternalPartialValues} externalValues - the external value list.
                 * @description the success callback of get partial values.
                 */
                export type GetPartialValuesSuccessCallbackType = 
                    (externalValues: GC.Spread.Sheets.ExternalPartialValues) => void
                
                /**
                 * Specifies the io error code.
                 * @enum {number}
                 */
                export enum ErrorCode{
                    /**
                     *  File read and write exception.
                     */
                    fileIOError= 0,
                    /**
                     *  Incorrect file format.
                     */
                    fileFormatError= 1,
                    /**
                     *  Need a password.
                     */
                    noPassword= 2,
                    /**
                     *  invalid Password.
                     */
                    invalidPassword= 3
                }

            }

            module NameBox{
                /**
                 * Gets the NameBox instance by the host element.
                 * @param {HTMLElement|string} host The host element or the host element id.
                 * @returns {GC.Spread.Sheets.NameBox.NameBox} The NameBox instance.
                 * @example
                 * ```javascript
                 * var spread = new GC.Spread.Sheets.Workbook("ss");
                 * var nameBox = new GC.Spread.Sheets.NameBox.NameBox('nameBox');
                 * nameBox.bind(spread);
                 * var nameBoxInstance = GC.Spread.Sheets.NameBox.findControl('nameBox');
                 * ```
                 */
                function findControl(host: HTMLElement|string): GC.Spread.Sheets.NameBox.NameBox;

                export interface INameBoxOptions{
                    dropDownMaxHeight?: number;
                    enableAddCustomName?: boolean;
                    enableNavigateToRange?: boolean;
                    showCustomNameListIndicator?: boolean;
                }


                export class NameBox{
                    /**
                     * Represents name box.
                     * @class
                     * @param {HTMLElement | string} host The DOM Element.
                     * @param {GC.Spread.Sheets.Workbook} spread The workbook which the namebox bound.
                     * @param {GC.Spread.Sheets.NameBox.INameBoxOptions} [options] options of the name box.
                     */
                    constructor(host: HTMLElement | string,  workbook: GC.Spread.Sheets.Workbook,  options?: GC.Spread.Sheets.NameBox.INameBoxOptions);
                    /**
                     * Indicates the options of the name box.
                     * @type {GC.Spread.Sheets.NameBox.INameBoxOptions}
                     * @property {boolean} [enableAddCustomName] Indicates whether enable add custom name when input a name which is not existed to the selector.
                     * @property {boolean} [enableNavigateToRange] Indicates whether enable navigate to the named range or drawing item when input its name or click on custom list item.
                     * @property {boolean} [showCustomNameList] Indicates whether show the custom name list dropdown indicator.
                     * @property {number} [dropDownMaxHeight] Indicates the drop down list element max height.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook(document.getElementById("ss"));
                     * var div = document.createElement('div');
                     * div.id = 'nameBox';
                     * div.style.width = '300px';
                     * div.style.height = '50px';
                     * document.getElementById('panel').appendChild(div);
                     *
                     * var nameBox = new GC.Spread.Sheets.NameBox.NameBox(document.getElementById('nameBox'), spread);
                     * nameBox.options.enableAddCustomName = false; // cannot add custom name with inputting in name box input box now.
                     * nameBox.options.enableNavigateToRange = false; // cannot swap the selected range to the value of the name box input box now.
                     * nameBox.options.showCustomNameList = false; // cannot open the custom name list by down arrow button right side and the button will be hidden now.
                     * nameBox.options.dropDownMaxHeight = 100; // the custom name list host DOM element height will no larger than 100px now.
                     *
                     * ```
                     */
                    options: GC.Spread.Sheets.NameBox.INameBoxOptions;
                    /**
                     * Dispose the NameBox and unbind all events.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook(document.getElementById("ss"));
                     * var nameBox = new GC.Spread.Sheets.NameBox.NameBox(document.getElementById('nameBox'), spread);
                     * // do something
                     * nameBox.dispose();
                     * ```
                     */
                    dispose(): void;
                    /**
                     * get the NameBox host element.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook(document.getElementById("ss"));
                     * var nameBox = new GC.Spread.Sheets.NameBox.NameBox(document.getElementById('nameBox'), spread);
                     * var host = nameBox.getHost();
                     * ```
                     */
                    getHost(): HTMLElement;
                    /**
                     * refresh the NameBox and sync the name box value to the work sheet selection.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook(document.getElementById("ss"));
                     * var nameBox = new GC.Spread.Sheets.NameBox.NameBox(document.getElementById('nameBox'), spread);
                     * var sheet = spread.getActiveSheet();
                     * sheet.setSelection(0, 0, 3, 3);
                     * nameBox.refresh();
                     * ```
                     */
                    refresh(): void;
                }
            }

