                export class TableSlicerData extends GC.Spread.Slicers.GeneralSlicerData{
                    /**
                     * Represents table slicer data.
                     * @extends GC.Spread.Slicers.GeneralSlicerData
                     * @class GC.Spread.Sheets.TableSlicerData
                     * @param {GC.Spread.Sheets.Tables.Table} table The table.
                     * @example
                     * ```javascript
                     * //This example creates a slicer for the table.
                     * var activeSheet = spread.getActiveSheet();
                     * //create table
                     * var dataSource = [
                     *     { Name: "Bob", City: "NewYork", Birthday: "1968/6/8" },
                     *     { Name: "Betty", City: "NewYork", Birthday: "1972/7/3" },
                     *     { Name: "Alice", City: "Washington", Birthday: "2012/2/15" },
                     * ];
                     * var table = activeSheet.tables.addFromDataSource("table1", 1, 1, dataSource);
                     * var slicerData = new GC.Spread.Sheets.Slicers.TableSlicerData(table);
                     * //Set slicer data to item slicer.
                     * var slicer = new GC.Spread.Sheets.Slicers.ItemSlicer("slicer", slicerData, "Name");
                     * //Add the item slicer to the dom tree.
                     * //The "slicerHost" is the div you want to add the slicer's dom to.
                     * document.getElementById("slicerHost").append(slicer.getDOMElement());
                     * ```
                     */
                    constructor(table: GC.Spread.Sheets.Tables.Table);
                    /**
                     * Filters the data that corresponds to the specified column name and exclusive data indexes.
                     * @param {string} columnName The column name.
                     * @param {GC.Spread.Slicers.ISlicerConditional} conditional The filter conditional.
                     * @param {boolean} [isPreview] Indicates whether filter is in preview mode.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook('ss');
                     * var activeSheet = spread.getActiveSheet();
                     * var dataSource = [
                     *     { Name: "Bob", City: "NewYork", Birthday: "1968/6/8" },
                     *     { Name: "Betty", City: "NewYork", Birthday: "1972/7/3" },
                     *     { Name: "Alice", City: "Washington", Birthday: "2012/2/15" },
                     * ];
                     * var table = activeSheet.tables.addFromDataSource("table1", 1, 1, dataSource);
                     * var slicerData = new GC.Spread.Sheets.Slicers.TableSlicerData(table);
                     * slicerData.getFilteredOutIndexes('Name', GC.Spread.Slicers.FilteredOutDataType.all); // []
                     * slicerData.doFilter('Name', {exclusiveRowIndexes: [0]});
                     * slicerData.getFilteredOutIndexes('Name', GC.Spread.Slicers.FilteredOutDataType.all); // [1, 2]
                     * ```
                     */
                    doFilter(columnName: string,  conditional: GC.Spread.Slicers.ISlicerConditional,  isPreview?: boolean): void;
                    /**
                     * Unfilter the data that corresponds to the specified column name.
                     * @param {string} columnName The column name.
                     * @example
                     * ```javascript
                     * var spread = new GC.Spread.Sheets.Workbook('ss');
                     * var activeSheet = spread.getActiveSheet();
                     * var dataSource = [
                     *     { Name: "Bob", City: "NewYork", Birthday: "1968/6/8" },
                     *     { Name: "Betty", City: "NewYork", Birthday: "1972/7/3" },
                     *     { Name: "Alice", City: "Washington", Birthday: "2012/2/15" },
                     * ];
                     * var table = activeSheet.tables.addFromDataSource("table1", 1, 1, dataSource);
                     * var slicerData = new GC.Spread.Sheets.Slicers.TableSlicerData(table);
                     * slicerData.getFilteredOutIndexes('Name', GC.Spread.Slicers.FilteredOutDataType.all); // []
                     * slicerData.doFilter('Name', {exclusiveRowIndexes: [0]});
                     * slicerData.getFilteredOutIndexes('Name', GC.Spread.Slicers.FilteredOutDataType.all); // [1, 2]
                     * slicerData.doUnfilter('Name');
                     * slicerData.getFilteredOutIndexes('Name', GC.Spread.Slicers.FilteredOutDataType.all); // []
                     * ```
                     */
                    doUnfilter(columnName: string): void;
                    /**
                     * Gets the table of the table slicer data.
                     * @returns {GC.Spread.Sheets.Tables.Table} The table of the table slicer data.
                     * @example
                     * ```javascript
                     * var activeSheet = spread.getActiveSheet();
                     * var dataSource = [
                     *     { Name: "Bob", City: "NewYork", Birthday: "1968/6/8" },
                     *     { Name: "Betty", City: "NewYork", Birthday: "1972/7/3" },
                     *     { Name: "Alice", City: "Washington", Birthday: "2012/2/15" },
                     * ];
                     * var table = activeSheet.tables.addFromDataSource("table1", 1, 1, dataSource);
                     * var slicerData = table.getSlicerData(); // GC.Spread.Sheets.Slicers.TableSlicerData
                     * console.log(slicerData.getTable() === table); // true
                     * ```
                     */
                    getTable(): GC.Spread.Sheets.Tables.Table;
                    /**
                     * Refreshes the table slicer data. will rebuild data source of table slicer data.
                     * @example
                     * ```javascript
                     * var activeSheet = spread.getActiveSheet();
                     * var sourceData = [["Date","Buyer","Type","Amount"],
                     *                  ["01-Jan","Mom","Fuel",74],
                     *                  ["15-Jan","Mom","Food",235],
                     *                  ["17-Jan","Dad","Sports",20],
                     *                  ["21-Jan","Kelly","Books",125]];
                     * activeSheet.setArray(0, 0, sourceData);
                     * var table = activeSheet.tables.add('sourceData', 0, 0, 5, 4);
                     * var slicerData = new GC.Spread.Sheets.Slicers.TableSlicerData(table);
                     * console.log(slicerData.getData("Amount")); // ['74', '235', '20', '125']
                     * activeSheet.setValue(1, 3, 99);
                     * console.log(slicerData.getData("Amount")); // ['74', '235', '20', '125']
                     * slicerData.refresh();
                     * console.log(slicerData.getData("Amount")); // ['99', '235', '20', '125']
                     * ```
                     */
                    refresh(): void;
                }

